// Generate script using Pollinations.ai (free, no key, unlimited)

const prompt = `Create a 3-minute nursery rhyme video for YouTube Kids (ages 2-5).

Output ONLY valid JSON with this exact structure:
{
  "title": "string - catchy, kid-friendly, < 60 chars",
  "description": "string - 2-3 sentences, includes keywords",
  "tags": ["string", "..."],
  "playlist": "string - playlist name or ID",
  "scenes": [
    {
      "id": 1,
      "duration": 12,
      "prompt": "string - detailed SDXL prompt for this scene: character + setting + mood + style. Consistent character description. 2D nursery rhyme illustration style, bright colors, simple shapes.",
      "lyrics": "string - 1-2 lines of lyrics shown on screen during this scene",
      "narration": "string - voiceover text for this scene (spoken, not sung)"
    }
    // ... 12-15 scenes total, durations sum to ~180 seconds
  ],
  "backgroundMusic": "string - mood/tempo for CC0 music search (e.g. 'cheerful acoustic ukulele 80bpm')"
}

Requirements:
- Main character: A friendly animated bunny named "Benny" - round, soft, big ears, blue shirt, always smiling
- Educational theme: colors, numbers, animals, or daily routines
- Simple repetitive lyrics kids can sing along
- Gentle, soothing tone
- Each scene 10-15 seconds
- Total ~180 seconds (3 minutes)
- Scene prompts must include: "Benny the bunny, round soft blue shirt, big ears, 2D vector illustration, nursery rhyme style, bright pastel colors, simple shapes, clean lines"
- Lyrics timed to match scene duration
- Narration separate from lyrics (spoken storyteller voice)`;

const response = await fetch('https://text.pollinations.ai/' + encodeURIComponent(prompt));
const text = await response.text();

return [{ json: { text } }];

// Parse Pollinations response and extract JSON
const response = $input.item.json;
let text = response.text || response.content || JSON.stringify(response);
text = text.replace(/```json|```/g, '').trim();
const parsed = JSON.parse(text);

return [{ json: parsed }];

// Generate images for all scenes using Pollinations.ai (free, no key)
// Character consistency via fixed prompt prefix + seed per character

const items = $input.all();
const script = items[0].json;
const scenes = script.scenes;
const CHARACTER_PROMPT = 'Benny the bunny, round soft blue shirt, big ears, 2D vector illustration, nursery rhyme style, bright pastel colors, simple shapes, clean lines';

const results = [];

for (const scene of scenes) {
  const fullPrompt = `${CHARACTER_PROMPT}, ${scene.prompt}`;
  const encoded = encodeURIComponent(fullPrompt);
  const seed = 12345 + scene.id;
  const url = `https://image.pollinations.ai/prompt/${encoded}?width=1920&height=1080&seed=${seed}&model=flux&nologo=true`;

  const imgResponse = await fetch(url);
  const buffer = await imgResponse.arrayBuffer();
  const base64 = Buffer.from(buffer).toString('base64');

  results.push({
    sceneId: scene.id,
    imageBase64: base64,
    prompt: fullPrompt
  });

  await new Promise(r => setTimeout(r, 1100));
}

return [{ json: { ...script, sceneImages: results } }];

// Generate voiceover using Edge TTS (Microsoft, free, no key)
// Returns audio buffer + timing for lyric sync

const script = $input.item.json;
const scenes = script.scenes;

let fullText = '';
const timing = [];
let currentTime = 0;

for (const scene of scenes) {
  if (scene.narration) {
    timing.push({ type: 'narration', sceneId: scene.id, start: currentTime, text: scene.narration });
    fullText += scene.narration + ' ';
    currentTime += scene.narration.length * 0.08;
  }
  if (scene.lyrics) {
    timing.push({ type: 'lyrics', sceneId: scene.id, start: currentTime, text: scene.lyrics, duration: scene.duration });
    fullText += scene.lyrics + ' ';
    currentTime += scene.duration;
  }
}

const voice = 'en-US-JennyNeural';
const ssml = `<speak version='1.0' xml:lang='en-US'><voice name='${voice}'>${fullText}</voice></speak>`;

const response = await fetch('https://edge.microsoft.com/translate/tts', {
  method: 'POST',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({ text: ssml, voice })
});

const audioBuffer = await response.arrayBuffer();
const audioBase64 = Buffer.from(audioBuffer).toString('base64');

return [{ json: { ...script, audioBase64, timing } }];
